SET secret_ciphertext = #{newCiphertext},
    kms_key_id = #{newKeyId},
    cipher_algorithm = #{newAlgorithm},
    cipher_version = #{newCipherVersion},
    rotated_at = #{rotatedAt},
    updated_at = #{rotatedAt},
    version = version + 1
WHERE tenant_id = #{tenantId}
